/**
 * Rebuilds src/roots.generated.ts from roots/*.pem, and refreshes the roots that ship with
 * Node's Mozilla CA bundle (listed in FROM_NODE) from the running Node version.
 *
 *   pnpm --filter @tap/anchor roots          # refresh and regenerate
 *   pnpm --filter @tap/anchor roots --check  # CI: fail if generated file is stale or a root expired,
 *                                            #     warn when a root expires within two years
 *
 * Roots not in Node's bundle (FreeTSA) are added by hand as roots/<name>.pem after checking their
 * fingerprint against the provider's website; docs/anchoring-providers.md lists the fingerprints.
 * Intermediate CAs that a TSA leaves out of its tokens go in roots/intermediates/ (they only help
 * build chains; trust still has to end at one of the roots).
 */
import { X509Certificate } from 'node:crypto';
import * as fs from 'node:fs';
import * as path from 'node:path';
import * as tls from 'node:tls';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const rootsDir = path.join(here, '..', 'roots');
const out = path.join(here, '..', 'src', 'roots.generated.ts');
const check = process.argv.includes('--check');

/** file name → exact subject CN in Node's bundle. */
const FROM_NODE: Record<string, string> = {
  'digicert-trusted-root-g4.pem': 'DigiCert Trusted Root G4',
  'usertrust-rsa-ca.pem': 'USERTrust RSA Certification Authority',
};

if (!check) {
  for (const [file, cn] of Object.entries(FROM_NODE)) {
    const pem = tls.rootCertificates.find((p) =>
      new X509Certificate(p).subject.split('\n').includes(`CN=${cn}`),
    );
    if (!pem) throw new Error(`${cn} is not in this Node version's CA bundle`);
    fs.writeFileSync(path.join(rootsDir, file), `${pem.trim()}\n`);
  }
}

let problems = 0;

function load(dir: string): string[] {
  if (!fs.existsSync(dir)) return [];
  const files = fs
    .readdirSync(dir)
    .filter((f) => f.endsWith('.pem'))
    .sort();
  const entries: string[] = [];
  for (const file of files) {
    const pem = fs.readFileSync(path.join(dir, file), 'utf8').trim();
    const cert = new X509Certificate(pem);
    const expires = new Date(cert.validTo).getTime();
    const days = Math.round((expires - Date.now()) / 86_400_000);
    const cn =
      cert.subject
        .split('\n')
        .find((l) => l.startsWith('CN='))
        ?.slice(3) ?? file;
    if (days < 0) {
      console.error(`EXPIRED: ${file} (${cn}) expired ${cert.validTo}`);
      problems++;
    } else if (days < 730) {
      console.warn(`warning: ${file} (${cn}) expires in ${days} days (${cert.validTo})`);
    }
    entries.push(
      `  // ${cn}, SHA-256 ${cert.fingerprint256}, valid to ${cert.validTo}\n  '${pem.replace(/\n/g, '\\n')}',`,
    );
  }
  return entries;
}

const roots = load(rootsDir);
const intermediates = load(path.join(rootsDir, 'intermediates'));
const list = (entries: string[]) => (entries.length > 0 ? `\n${entries.join('\n')}\n` : '');
const source = `// Generated by scripts/refresh-roots.ts from roots/*.pem. Do not edit by hand.
/** Trusted timestamp-authority roots (PEM). */
export const ROOT_PEMS: readonly string[] = [${list(roots)}];

/** Intermediate CAs some TSAs leave out of their tokens (PEM). Not trusted by themselves. */
export const INTERMEDIATE_PEMS: readonly string[] = [${list(intermediates)}];
`;
if (check) {
  const current = fs.existsSync(out) ? fs.readFileSync(out, 'utf8') : '';
  if (current !== source) {
    console.error('src/roots.generated.ts is out of date: run pnpm --filter @tap/anchor roots');
    problems++;
  }
  if (problems > 0) process.exit(1);
  console.log(`${roots.length} trusted roots and ${intermediates.length} intermediates, all valid.`);
} else {
  fs.writeFileSync(out, source);
  console.log(
    `Wrote ${roots.length} roots and ${intermediates.length} intermediates to src/roots.generated.ts`,
  );
}
